const n={loading:n=>{const{normalize:r}=n;return r(["लोड हो रहा है"])},Ranking:n=>{const{normalize:r}=n;return r(["श्रेणी"])},Daily:n=>{const{normalize:r}=n;return r(["दैनिक"])},Weekly:n=>{const{normalize:r}=n;return r(["साप्ताहिक"])},Monthly:n=>{const{normalize:r}=n;return r(["महीने के"])},Duration:n=>{const{normalize:r,interpolate:t,named:o}=n;return r(["समयावधि ",t(o("duration"))])},OnlyShowTop:n=>{const{normalize:r,interpolate:t,named:o}=n;return r(["रैंकिंग सूची केवल शीर्ष ",t(o("num"))," दिखाती है"])},i_got_it:n=>{const{normalize:r}=n;return r(["पाना"])},levelCount:n=>{const{normalize:r,interpolate:t,named:o}=n;return r(["Lv.",t(o("count"))])},honor:n=>{const{normalize:r}=n;return r(["सम्मान"])},charm:n=>{const{normalize:r}=n;return r(["आकर्षण"])},room:n=>{const{normalize:r}=n;return r(["रूम"])},honor_tip:n=>{const{normalize:r}=n;return r(["आकर्षण रैंकिंग आपके द्वारा भेजे गए सिक्कों की संख्या पर निर्भर करती है लकी उपहारों की गिनती सिक्के के मूल्य का केवल 20% होती है"])},charm_tip:n=>{const{normalize:r}=n;return r(["आकर्षण रैंकिंग आपको प्राप्त हीरों की संख्या से निर्धारित होती है लकी गिफ्ट हीरे के मूल्य का केवल 20% ही गिना जाता है"])},room_tip:n=>{const{normalize:r}=n;return r(["रूम की रैंकिंग रूम में प्राप्त सिक्कों की संख्या से निर्धारित होती है, लकी उपहारों की गिनती सिक्के के मूल्य का केवल 20% होती है"])},viewLimit:n=>{const{normalize:r}=n;return r(["केवल लेवल 10 या उससे ऊपर ही देख सकते हैं।"])},statementLang:n=>{const{normalize:r}=n;return r(["इस इवेंट का Google Play से कोई संबंध नहीं है। सभी अधिकार इस ऐप द्वारा सुरक्षित हैं।"])},statementIosLang:n=>{const{normalize:r}=n;return r(["इस इवेंट का Apple Inc. से कोई संबंध नहीं है। सभी अधिकार इस ऐप द्वारा सुरक्षित हैं।"])}};export{n as default};
